example_code:
ocene = {"Marko": 4, "Ana": 5, "Iva": 3}

for ime, ocena in ocene.items():
    print(ime, "→", ocena)

for ime in sorted(ocene):
    print("Abecedno:", ime)

vrednosti = list(ocene.values())
print("Prosek:", sum(vrednosti) / len(vrednosti))
print("Najbolja:", max(vrednosti), "Najslabija:", min(vrednosti))

for i, ime in enumerate(sorted(ocene), start=1):
    print(f"{i}. {ime}")

