exercise.solution:
ocene = {}

# Učitavaj redove „Ime ocena“ dok red nije prazan.
while True:
    red = input("Učenik i ocena: ")
    if red == "":
        break
    ime, ocena = red.split()
    ocene[ime] = int(ocena)

# Ispiši učenike abecedno i prosek.
for ime in sorted(ocene):
    print(f"{ime}: {ocene[ime]}")
prosek = sum(ocene.values()) / len(ocene)
print(f"Prosek: {prosek:.2f}")
